Item.method_code:
string webServiceId = this.getProperty("source_id");

Item webServiceRequest = this.newItem("cws_WebService", "get");
webServiceRequest.setID(webServiceId);
webServiceRequest.setAttribute("select", "id");

Item webServiceItem = webServiceRequest.apply();
if (webServiceItem.isError() && webServiceItem.isEmpty())
{
  throw new InvalidOperationException(CCO.ErrorLookup.Lookup("cws_MissingWebService"));
}

return this;
